"""Exact and floating-point verification of the rising-factorial identity
   Gamma(x+m)/Gamma(x) = x (x+1) ... (x+m-1)."""
import math
from fractions import Fraction
from typing import List


def rising_factorial(x: float, m: int) -> float:
    prod = 1.0
    for i in range(m):
        prod *= (x + i)
    return prod


def gamma_ratio(x: float, m: int) -> float:
    return math.gamma(x + m) / math.gamma(x)


def rising_factorial_exact(x: Fraction, m: int) -> Fraction:
    prod = Fraction(1)
    for i in range(m):
        prod *= (x + i)
    return prod


def main() -> None:
    cases: List[tuple] = [(2.5, 4), (0.75, 5), (3.0, 3), (1.2, 6)]
    for x, m in cases:
        print(f"x={x}, m={m}: gamma-ratio={gamma_ratio(x, m):.10f} "
              f"product={rising_factorial(x, m):.10f}")
    print("exact (7/3, 4):", rising_factorial_exact(Fraction(7, 3), 4))


if __name__ == "__main__":
    main()

"""Numerical verification of the Beta-moment telescoping law: under additive
chaining a_{j+1} = a_j + b_j, the product of per-stage Beta moments equals the
endpoint ratio of Gamma factors."""
import math
from typing import List, Sequence, Tuple


def beta_moment(a: float, b: float, p: float) -> float:
    return (math.gamma(a + p) * math.gamma(a + b)) / (
        math.gamma(a) * math.gamma(a + b + p))


def chained(a0: float, betas: Sequence[float]) -> Tuple[List[float], List[float], float]:
    a = [a0]
    for b in betas:
        a.append(a[-1] + b)
    return a[:-1], list(betas), a[-1]


def direct(alpha: Sequence[float], beta: Sequence[float], p: float) -> float:
    r = 1.0
    for a, b in zip(alpha, beta):
        r *= beta_moment(a, b, p)
    return r


def endpoint(a0: float, an: float, p: float) -> float:
    return (math.gamma(a0 + p) * math.gamma(an)) / (math.gamma(a0) * math.gamma(an + p))


def main() -> None:
    alpha, beta, an = chained(1.3, [0.7, 1.1, 0.5, 0.9, 1.4])
    for p in [2.0, 0.5, -0.3, 3.0]:
        lhs, rhs = direct(alpha, beta, p), endpoint(1.3, an, p)
        print(f"p={p}: direct={lhs:.12f} endpoint={rhs:.12f} diff={abs(lhs-rhs):.1e}")


if __name__ == "__main__":
    main()

