function GrowDDAG(d, N):
    for n in d .. N-1:
        parents[n] <- sample d distinct from {0..n-1}
    return parents

function JointDescendants(block, parents, N):
    for each seed v in block:
        mark v; for w in v+1 .. N-1:
            if any parent of w is marked: mark w
